int main(int argc,char **argv){if(argc!=3&&argc!=4)return 2;try{auto module=LoadLibraryW(L"maclauncher-xess-gpu.dll");if(!module)return 3;auto bridge=reinterpret_cast<MLXessBridge>(GetProcAddress(module,"mlXessBridge"));if(!bridge)return 3;MLXessCall call{};call.size=sizeof(call);call.version=ML_XESS_VERSION;std::snprintf(call.endpoint,sizeof(call.endpoint),"%s",argv[1]);if(argc==4)std::snprintf(call.message,sizeof(call.message),"%s",argv[3]);if(bridge(ML_XESS_INIT,&call))throw std::runtime_error("The XeSS Vulkan native service could not connect");if(argc==4){std::printf("MACLAUNCHER_XESS_HELPER {\"pid\":%d,\"token\":\"%s\"}\n",call.process,argv[3]);std::fflush(stdout);std::thread([]{for(;;){Sleep(1000);DWORD written=0;const char alive[]="MACLAUNCHER_GPU_ALIVE\n";if(!WriteFile(GetStdHandle(STD_OUTPUT_HANDLE),alive,sizeof(alive)-1,&written,nullptr))ExitProcess(0);}}).detach();}auto host=new Host(argv[2],bridge);for(;;){call={};call.size=sizeof(call);call.version=ML_XESS_VERSION;if(bridge(ML_XESS_NEXT,&call))throw std::runtime_error("The Vulkan XeSS scene could not be received");if(call.command==ML_XESS_CLOSE)return 0;try{if(call.command==ML_XESS_CONFIGURE){host->configure(call);call.status=0;bridge(ML_XESS_READY,&call);}else if(call.command==ML_XESS_FRAME)host->encode(call);}catch(const std::exception &error){call.status=-1;std::snprintf(call.message,sizeof(call.message),"%s",error.what());bridge(call.command==ML_XESS_CONFIGURE?ML_XESS_READY:ML_XESS_FAILURE,&call);}}}catch(const std::exception &error){std::fprintf(stderr,"%s\n",error.what());return 4;}}
